package com.nimbusbill.customer.repository; import com.nimbusbill.customer.entity.CustomerPricingAssignment; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*;
public interface CustomerPricingAssignmentRepository extends JpaRepository<CustomerPricingAssignment,UUID>{List<CustomerPricingAssignment> findByCustomerIdOrderByEffectiveFromDesc(UUID customerId);@Query("select a from CustomerPricingAssignment a where a.customer.id=:customerId and a.active=true and a.effectiveFrom<=:date and (a.effectiveTo is null or a.effectiveTo>=:date) order by a.effectiveFrom desc") List<CustomerPricingAssignment> activeAt(@Param("customerId") UUID customerId,@Param("date") LocalDate date);}
